// ── Client Configuration ──
// PRODUCTION: Replace with Google Sheets node reading "Clients" tab.
// Columns: clientName, contactEmail, company, channels (comma-sep), reportDay
const clients = [
  {
    clientId: "CLT-001",
    clientName: "Sarah Mitchell",
    contactEmail: "sarah@brightwavecoffee.com",
    company: "Brightwave Coffee",
    industry: "E-commerce (DTC)",
    channels: ["Google Ads", "Meta Ads", "Email"],
    agencyOwner: "Alex Rivera",
    reportDay: "Monday"
  },
  {
    clientId: "CLT-002",
    clientName: "Marcus Chen",
    contactEmail: "marcus@fitlifestudios.com",
    company: "FitLife Studios",
    industry: "Fitness / Wellness",
    channels: ["Meta Ads", "Email", "SEO"],
    agencyOwner: "Alex Rivera",
    reportDay: "Monday"
  },
  {
    clientId: "CLT-003",
    clientName: "Diana Torres",
    contactEmail: "diana@greenscapellc.com",
    company: "GreenScape Landscaping",
    industry: "Local Services",
    channels: ["Google Ads", "SEO"],
    agencyOwner: "Alex Rivera",
    reportDay: "Monday"
  }
];
return clients.map(c => ({ json: { ...c, EventKey: "report:" + c.clientId + ":" + new Date().toISOString().slice(0,10) } }));

// ── Weekly Metrics Fetch ──
// PRODUCTION: Replace with Google Sheets node reading "Metrics" tab,
// or API nodes (Google Ads API, Meta Marketing API, GA4).
// Each client gets per-channel KPIs with week-over-week deltas.
const metricsDB = {
  "CLT-001": {
    period: "Jul 21 – Jul 27, 2026",
    channels: {
      "Google Ads": { spend: 2840, impressions: 184200, clicks: 5526, ctr: 3.0, conversions: 187, cpa: 15.19, revenue: 11220, roas: 3.95 },
      "Meta Ads":   { spend: 1960, impressions: 312400, clicks: 4686, ctr: 1.5, conversions: 142, cpa: 13.80, revenue: 7810, roas: 3.98 },
      "Email":      { spend: 0, impressions: 28400, clicks: 3124, ctr: 11.0, conversions: 94, cpa: 0, revenue: 5640, roas: null }
    },
    prevWeek: { totalSpend: 5100, totalConversions: 389, totalRevenue: 22840, blendedRoas: 4.48, blendedCpa: 13.11 }
  },
  "CLT-002": {
    period: "Jul 21 – Jul 27, 2026",
    channels: {
      "Meta Ads": { spend: 3200, impressions: 428000, clicks: 8560, ctr: 2.0, conversions: 214, cpa: 14.95, revenue: 12840, roas: 4.01 },
      "Email":    { spend: 0, impressions: 15200, clicks: 1976, ctr: 13.0, conversions: 68, cpa: 0, revenue: 4080, roas: null },
      "SEO":      { spend: 0, impressions: 42800, clicks: 2140, ctr: 5.0, conversions: 43, cpa: 0, revenue: 2580, roas: null }
    },
    prevWeek: { totalSpend: 3200, totalConversions: 298, totalRevenue: 17820, blendedRoas: 5.57, blendedCpa: 10.74 }
  },
  "CLT-003": {
    period: "Jul 21 – Jul 27, 2026",
    channels: {
      "Google Ads": { spend: 1450, impressions: 68400, clicks: 3420, ctr: 5.0, conversions: 96, cpa: 15.10, revenue: 8640, roas: 5.96 },
      "SEO":        { spend: 0, impressions: 24600, clicks: 1230, ctr: 5.0, conversions: 31, cpa: 0, revenue: 2790, roas: null }
    },
    prevWeek: { totalSpend: 1520, totalConversions: 112, totalRevenue: 9480, blendedRoas: 6.24, blendedCpa: 13.57 }
  }
};
const client = $json;
const m = metricsDB[client.clientId];
if (!m) return { json: { ...client, metrics_valid: false, error: "No metrics found for " + client.clientId } };
// Compute blended totals
let totalSpend = 0, totalConv = 0, totalRev = 0;
for (const ch of Object.values(m.channels)) { totalSpend += ch.spend; totalConv += ch.conversions; totalRev += ch.revenue; }
const blendedRoas = totalSpend > 0 ? +(totalRev / totalSpend).toFixed(2) : null;
const blendedCpa = totalConv > 0 ? +(totalSpend / totalConv).toFixed(2) : 0;
const pw = m.prevWeek;
return { json: {
  ...client,
  period: m.period,
  channels: m.channels,
  totals: { spend: totalSpend, conversions: totalConv, revenue: totalRev, roas: blendedRoas, cpa: blendedCpa },
  deltas: {
    spend: pw.totalSpend ? +((totalSpend - pw.totalSpend) / pw.totalSpend * 100).toFixed(1) : 0,
    conversions: pw.totalConversions ? +((totalConv - pw.totalConversions) / pw.totalConversions * 100).toFixed(1) : 0,
    revenue: pw.totalRevenue ? +((totalRev - pw.totalRevenue) / pw.totalRevenue * 100).toFixed(1) : 0,
    roas: pw.blendedRoas && blendedRoas ? +((blendedRoas - pw.blendedRoas) / pw.blendedRoas * 100).toFixed(1) : 0,
    cpa: pw.blendedCpa && blendedCpa ? +((blendedCpa - pw.blendedCpa) / pw.blendedCpa * 100).toFixed(1) : 0
  },
  prevWeek: pw,
  metrics_valid: true,
  Timestamp: new Date().toISOString()
}};

const d = $json;
const ok = d.metrics_valid === true
  && d.totals && typeof d.totals.spend === 'number'
  && d.channels && Object.keys(d.channels).length > 0
  && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(d.contactEmail || ''));
if (!ok) return { json: { Timestamp: new Date().toISOString(), EventKey: d.EventKey || 'unknown',
  Workflow: 'agency-reporting', Status: 'rejected_invalid_metrics', ClientId: d.clientId || 'unknown',
  Error: d.error || 'Validation failed' } };
return { json: { ...d, input_valid: true } };

// ── Idempotency Guard ──
// PRODUCTION: Check Sheets "Report Log" tab for existing EventKey.
// If found → skip (already sent this week). If not → proceed.
// Demo: always proceeds (no prior sends).
const d = $json;
const alreadySent = false; // PRODUCTION: query Sheets for EventKey match
return { json: { ...d, already_sent: alreadySent } };

const raw = $json.content?.parts?.filter(p => !p.thought).map(p => p.text || '').join('') ?? $json.text ?? '';
let narrative = '';
const start = raw.lastIndexOf('<<<REPORT>>>');
if (start !== -1) {
  narrative = raw.slice(start + 12);
  const end = narrative.indexOf('<<<END>>>');
  if (end !== -1) narrative = narrative.slice(0, end);
  narrative = narrative.trim();
}
if (narrative.length < 50) narrative = raw.trim();
const client = $('Idempotency Check').item.json;
const confidence = narrative.length > 100 ? 0.92 : 0.55;
return { json: { ...client, narrative, ai_confidence: confidence,
  Timestamp: new Date().toISOString() } };

